#!/usr/bin/env python3
import csv, json
from datetime import datetime
from decimal import Decimal, getcontext

getcontext().prec = 20
READINGS = '/app/readings.csv'
OUT = '/app/answer.json'
START = datetime.fromisoformat('2026-11-01T00:00:00')
END = datetime.fromisoformat('2026-12-01T00:00:00')
ROLLOVER_MODULUS_KWH = Decimal('1000000.0')  # 0.0 through 999999.9, then wraps to 0.0

rows = []
with open(READINGS, newline='') as f:
    for row in csv.DictReader(f):
        rows.append((datetime.fromisoformat(row['ts']), Decimal(row['register_kwh']), row['meter_id']))
rows.sort(key=lambda x: x[0])

flags = []
# Basic data checks
if len({m for _, _, m in rows}) != 1:
    flags.append('multiple_meters')
if len({ts for ts, _, _ in rows}) != len(rows):
    flags.append('duplicate_timestamps')

# Unwrap cumulative register and record rollovers/gaps.
unwrapped = []
offset = Decimal('0')
rollovers = []
gaps = []
prev = None
for ts, val, meter in rows:
    if prev is not None:
        pts, pval, _ = prev
        hours = (ts - pts).total_seconds() / 3600
        if hours != 1:
            gaps.append((pts.isoformat(), ts.isoformat(), hours))
        if val < pval:
            offset += ROLLOVER_MODULUS_KWH
            rollovers.append((pts.isoformat() + 'Z', ts.isoformat() + 'Z'))
    unwrapped.append((ts, val + offset, val))
    prev = (ts, val, meter)

if gaps:
    flags.append('non_hourly_gaps')
if rollovers:
    flags.append('register_rollover')

lookup = {ts: (uw, raw) for ts, uw, raw in unwrapped}
if START not in lookup or END not in lookup:
    result = {
        'status': 'cannot_determine',
        'reason': 'required interval endpoint readings are missing',
        'flags': flags,
    }
else:
    # Sum all fully covered hourly intervals in (START, END].
    total = Decimal('0')
    intervals = 0
    for (a, uwa, _), (b, uwb, _) in zip(unwrapped, unwrapped[1:]):
        if a >= START and b <= END:
            total += uwb - uwa
            intervals += 1
    endpoint_total = lookup[END][0] - lookup[START][0]
    if total != endpoint_total:
        flags.append('endpoint_sum_mismatch')
    if intervals != int((END - START).total_seconds() // 3600):
        flags.append('incomplete_interval_coverage')
    if 'non_hourly_gaps' in flags or 'endpoint_sum_mismatch' in flags or 'incomplete_interval_coverage' in flags:
        result = {
            'status': 'cannot_determine',
            'reason': 'data coverage or consistency checks failed',
            'flags': flags,
        }
    else:
        # Decimal has one decimal place from the source register; JSON number is safe here.
        result = {'answer': float(total), 'flags': flags}

with open(OUT, 'w') as f:
    json.dump(result, f, separators=(',', ':'))
    f.write('\n')
print(json.dumps(result, indent=2))
