import csv, datetime as dt, json

FMT = '%Y-%m-%dT%H:%M:%S'
ROLLOVER_BASE = 1_000_000.0  # EM-300 register rolls after 999999.9 to 0.0
START = dt.datetime(2026, 11, 1, 0, 0)
END = dt.datetime(2026, 12, 1, 0, 0)

rows = []
with open('readings.csv', newline='') as f:
    for row in csv.DictReader(f):
        rows.append((dt.datetime.strptime(row['ts'], FMT), float(row['register_kwh'])))
rows.sort()

by_ts = {t: r for t, r in rows}
flags = []
if len(by_ts) != len(rows):
    flags.append('duplicate_timestamps')

# Verify hourly continuity over the full file.
for (t0, _), (t1, _) in zip(rows, rows[1:]):
    if t1 - t0 != dt.timedelta(hours=1):
        flags.append('non_hourly_gap')
        break

if START not in by_ts or END not in by_ts:
    out = {'status': 'cannot_determine', 'reason': 'missing requested boundary reading(s)', 'flags': flags}
else:
    total = 0.0
    rollover_seen = False
    counted = 0
    for (t0, r0), (t1, r1) in zip(rows, rows[1:]):
        if START < t1 <= END:
            inc = r1 - r0
            if inc < 0:
                inc = (ROLLOVER_BASE - r0) + r1
                rollover_seen = True
            total += inc
            counted += 1
    if counted != int((END - START).total_seconds() // 3600):
        flags.append('unexpected_interval_count')
    if rollover_seen:
        flags.append('register_rollover_corrected')
    out = {'answer': round(total, 1), 'flags': flags}

with open('answer.json', 'w') as f:
    json.dump(out, f, separators=(',', ':'))
    f.write('\n')
print(json.dumps(out, indent=2))
